def vary(example, rng):
    g=[row[:] for row in example]
    H,W=len(g),len(g[0])
    # retain the 3x3 compartment scaffold, while vary the colored motifs' locations
    # choose several compartments and place motifs sampled from existing motif shapes
    for r in range(H):
        for c in range(W):
            if g[r][c]==9: g[r][c]=0
    # motif templates observed, in local coordinates within 5x5 cells
    motifs=[[(1,2),(2,1),(2,2),(2,3),(3,2)],[(2,2),(2,3),(3,3)],[(2,3),(3,3)],[(1,3),(2,2),(2,3),(3,3)]]
    cells=[(0,0),(0,1),(0,2),(1,0),(1,1),(1,2),(2,0),(2,1),(2,2)]
    rng.shuffle(cells)
    for cr,cc in cells[:rng.randint(3,6)]:
        mot=rng.choice(motifs)
        # 5x5 compartments separated by walls at 5,11
        ro,co=cr*6,cc*6
        for dr,dc in mot:
            if ro+dr<H and co+dc<W and g[ro+dr][co+dc]==0:
                g[ro+dr][co+dc]=9
    return g
