        for c in range(W): g[x][c]=7
    for y in (5,11):
        for r in range(H): g[r][y]=7
    motifs=[[(1,2),(2,1),(2,2),(2,3),(3,2)],[(1,2),(1,3),(2,3)],[(2,2),(3,2)],[(1,3),(2,2),(2,3),(3,3)]]
