    rng.shuffle(cells)
    for cr,cc in cells[:rng.randint(1,8)]:
        pts=rng.choice(motifs); k=rng.randrange(4)
        for dr,dc in pts:
            for _ in range(k): dr,dc=dc,4-dr
            rr,cc2=cr*6+dr,cc*6+dc
            if 0<=rr<H and 0<=cc2<W and g[rr][cc2]==0: g[rr][cc2]=rng.choice([9,9,9])
    return g
